css:
:scope { width: min(100%, 1294px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 3; grid-row: 1 / span 7; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i2 { grid-column: 4 / span 14; grid-row: 28 / span 10; font-family: var(--os-font-heading); font-size: 83.2px; font-weight: 380; line-height: 1; letter-spacing: -0.025em; color: var(--os-color-surface); }
.gx__i3 { grid-column: 4 / span 13; grid-row: 42 / span 12; font-family: var(--os-font-heading); font-size: 36.8px; font-weight: 380; line-height: 1.25; letter-spacing: -0.01em; color: var(--os-color-surface); }
.gx__i4 { grid-column: 4 / span 10; grid-row: 65 / span 4; font-family: var(--os-font-heading); font-size: 25.6px; font-weight: 380; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-surface); }
.gx__i5 { grid-column: 15 / span 10; grid-row: 65 / span 4; font-family: var(--os-font-heading); font-size: 25.6px; font-weight: 380; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-surface); }
.gx__i6 { grid-column: 4 / span 10; grid-row: 71 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-surface); }
.gx__i7 { grid-column: 15 / span 10; grid-row: 70 / span 6; font-family: var(--os-font-heading); font-size: 36.8px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: inherit; }
.gx__i8 { grid-column: 4 / span 10; grid-row: 77 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-surface); }
.gx__i9 { grid-column: 15 / span 10; grid-row: 77 / span 6; font-family: var(--os-font-heading); font-size: 36.8px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: inherit; }
.gx__i10 { grid-column: 4 / span 10; grid-row: 81 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-surface); }
.gx__i11 { grid-column: 4 / span 10; grid-row: 86 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-surface); }
.gx__i12 { grid-column: 15 / span 10; grid-row: 85 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-surface); }
.gx__i13 { grid-column: 4 / span 10; grid-row: 92 / span 6; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-border); }
.gx__i14 { grid-column: 15 / span 10; grid-row: 91 / span 3; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-border); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 67px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 29px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 20px; }
  .gx__i5 { font-family: var(--os-font-heading); font-size: 20px; }
  .gx__i6 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i7 { font-family: var(--os-font-heading); font-size: 29px; }
  .gx__i8 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i9 { font-family: var(--os-font-heading); font-size: 29px; }
  .gx__i10 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i13 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i14 { font-family: var(--os-font-label); font-size: 14px; }
}
